create table public."Claims" (
  "Id" bigint generated by default as identity not null,
  "Type" character varying null,
  "Value" character varying null,
  "Description" text null,
  "ModuleId" bigint null,
  "SubModuleId" bigint null,
  "System" boolean null,
  "CorporationId" bigint null,
  constraint "Claims_pkey" primary key ("Id"),
  constraint "Claims_CorporationId_fkey" foreign KEY ("CorporationId") references "Corporations" (id),
  constraint "Claims_ModuleId_fkey" foreign KEY ("ModuleId") references "Modules" (id),
  constraint "Claims_SubModuleId_fkey" foreign KEY ("SubModuleId") references "SubModules" (id)
) TABLESPACE pg_default;